<?php
$id=(int)($_GET['id']??0);
$l=DB::row('SELECT l.*,COALESCE(c.keyword,l.category) keyword,c.location FROM leads l LEFT JOIN campaigns c ON c.id=l.campaign_id WHERE l.id=?',[$id]);
if(!$l){flash('Record not found.','err');redirect(url('leads'));}
if(is_post()){
  $a=$_POST['a']??'';
  try{
  switch($a){
    case 'save':
      $u=array_intersect_key(array_map(fn($v)=>is_string($v)?trim($v):$v,$_POST),array_flip(array_merge(CRM::CORE,['assigned_to','notes'])));
      $u['deal_value']=($u['deal_value']??'')!==''?(float)$u['deal_value']:null;
      $u['follow_up_at']=($u['follow_up_at']??'')!==''?date('Y-m-d H:i:s',strtotime($u['follow_up_at'])):null;
      $u['assigned_to']=(int)($u['assigned_to']??0)?:null;
      if(isset($u['phone'])&&$u['phone']!==$l['phone'])$u['phone_source']=$u['phone']?'manual':'';
      $oldTags=array_filter(array_map('trim',explode(',',(string)$l['tags'])));
      DB::update('leads',$u,'id=?',[$id]);
      CRM::saveCustom($id,$_POST['cf']??[]);
      foreach(array_diff(array_filter(array_map('trim',explode(',',(string)($u['tags']??'')))),$oldTags) as $t)Automation::fire('tag_added',$id,['tag'=>$t]);
      if(!empty($_POST['status'])&&$_POST['status']!==$l['status'])CRM::setStatus($id,$_POST['status']);
      event($id,'note','Details updated');flash('Saved.');break;
    case 'status':CRM::setStatus($id,$_POST['status']??'new');flash('Status updated.');break;
    case 'promote':Outreach::promote($id);flash('Moved to Leads.');break;
    case 'abort':Queue::abort([$id]);flash('Process stopped.');break;
    case 'initiate':Outreach::initiate([$id],['auto'=>!empty($_POST['auto']),'pw'=>$_POST['pw']??0,'pn'=>$_POST['pn']??0]);flash('Audit & report started – watch the progress here.');break;
    case 'report':DB::q("DELETE FROM jobs WHERE ref_id=? AND type='report' AND status='pending'",[$id]);DB::update('leads',['abort_flag'=>0,'progress'=>58,'progress_msg'=>'Queued for AI report','stage'=>'queued'],'id=?',[$id]);Queue::push('report',$id,['pw'=>$_POST['pw']??0,'pn'=>$_POST['pn']??0]);event($id,'stage','Report regeneration queued');flash('Report regeneration queued.');break;
    case 'send':
      $ch=array_values(array_intersect($_POST['ch']??[],['email','whatsapp']));
      if(!$ch)throw new Exception('Choose at least one channel.');
      if(in_array('email',$ch,true))DB::update('leads',['email_status'=>''],'id=? AND email_status=\'failed\'',[$id]);
      if(in_array('whatsapp',$ch,true))DB::update('leads',['wa_status'=>''],'id=? AND wa_status IN (\'failed\',\'queued\')',[$id]);
      DB::q("DELETE FROM jobs WHERE type='contact' AND ref_id=? AND status='pending'",[$id]);
      DB::update('leads',['abort_flag'=>0],'id=?',[$id]);
      Queue::push('contact',$id,['channels'=>$ch,'force'=>1]);event($id,'scheduled','Outreach queued manually ('.implode(' + ',$ch).')');flash('Sending now…');break;
    case 'wa_done':
      [,$b]=Outreach::message($l['website']?'whatsapp':'whatsapp_noweb',$l);
      DB::insert('messages',['lead_id'=>$id,'channel'=>'whatsapp','status'=>'manual','body'=>tpl($b,lead_vars($l))]);
      DB::update('leads',['wa_status'=>'manual'],'id=?',[$id]);
      if(!in_array($l['stage'],['opened','replied','won','lost'],true))stage($id,'contacted');
      if($l['is_lead']&&$l['status']==='new')CRM::setStatus($id,'contacted');
      event($id,'sent','WhatsApp sent manually with the PDF','whatsapp');json_out(['ok'=>1]);
    case 'replied':Outreach::markReplied($id,in_array($_POST['via']??'',['email','whatsapp','call','other'],true)?$_POST['via']:'other',trim($_POST['msg']??''));flash('Reply logged.');break;
    case 'won':stage($id,'won','Marked as Won');Outreach::promote($id,'won');CRM::setStatus($id,'won');flash('Marked as won 🎉');break;
    case 'lost':stage($id,'lost','Marked as Not interested');if($l['is_lead'])CRM::setStatus($id,'lost');flash('Marked as not interested.');break;
    case 'note':if($t=trim($_POST['note']??''))event($id,'note',$t);break;
    case 'book':$t=strtotime($_POST['at']??'');if(!$t)throw new Exception('Pick a date and time.');Booking::book($id,$t,'admin',trim($_POST['notes']??''));flash('Appointment booked.');break;
    case 'appt':DB::update('appointments',['status'=>$_POST['st']],'id=? AND lead_id=?',[(int)$_POST['aid'],$id]);event($id,'note','Appointment marked '.$_POST['st']);break;
    case 'call':Voice::start($id,['task'=>trim($_POST['task']??''),'first'=>trim($_POST['first']??'')]);flash('AI call started – the result will appear in the journey.');break;
    case 'auto':$au=DB::row('SELECT * FROM automations WHERE id=?',[(int)$_POST['aid']]);if($au&&Automation::start($au,$id,true))flash('Automation started.');else flash('This lead does not match the automation conditions.','warn');break;
    case 'cancelrun':Automation::cancel((int)$_POST['rid']);flash('Automation stopped for this lead.');break;
    case 'delete':Outreach::bulk('delete',[$id]);flash('Deleted.');redirect(url($l['is_lead']?'leads':'prospects'));}}
  catch(Throwable $e){flash(e($e->getMessage()),'err');}
  redirect(url('lead',['id'=>$id]));}
$title=$l['contact_name']&&$l['is_lead']?$l['contact_name']:$l['name'];
$subtitle=implode(' · ',array_filter([$l['contact_name']&&$l['is_lead']&&$l['name']!==$l['contact_name']?$l['name']:'',$l['category'],$l['city']]));
$au=jd($l['audit']);$cf=jd($l['custom']);$soc=jd($l['socials']);
$rep=DB::row('SELECT * FROM reports WHERE lead_id=? ORDER BY id DESC LIMIT 1',[$id]);
$ev=DB::all('SELECT * FROM events WHERE lead_id=? ORDER BY id DESC LIMIT 250',[$id]);
$msgs=DB::all('SELECT * FROM messages WHERE lead_id=? ORDER BY id DESC',[$id]);
$appts=DB::all('SELECT * FROM appointments WHERE lead_id=? ORDER BY start_at DESC',[$id]);
$calls=DB::all('SELECT * FROM calls WHERE lead_id=? ORDER BY id DESC',[$id]);
$runs=DB::all('SELECT r.*,a.name FROM automation_runs r JOIN automations a ON a.id=r.automation_id WHERE r.lead_id=? ORDER BY r.id DESC LIMIT 20',[$id]);
$autos=DB::all('SELECT id,name FROM automations ORDER BY name');
$users=DB::all('SELECT id,name FROM users ORDER BY name');
$failedJob=DB::row("SELECT type,error FROM jobs WHERE ref_id=? AND type IN ('audit','report','contact') AND status='failed' ORDER BY id DESC LIMIT 1",[$id]);
$busy=in_array($l['stage'],['queued','auditing','reporting','contacting'],true);
$waText='';$waLink='';
if($l['phone']){[,$b]=Outreach::message($l['website']?'whatsapp':'whatsapp_noweb',$l);$waText=tpl($b,lead_vars($l));$waLink=WhatsApp::link($l['phone'],$waText);}
$pw=DB::all("SELECT id,name,is_active FROM prompts WHERE type='report_website' ORDER BY is_active DESC,name");
$pn=DB::all("SELECT id,name,is_active FROM prompts WHERE type='report_noweb' ORDER BY is_active DESC,name");
$psel=fn($n,$rows)=>'<select name="'.$n.'">'.implode('',array_map(fn($p)=>'<option value="'.$p['id'].'">'.e($p['name']).($p['is_active']?' (in use)':'').'</option>',$rows)).'</select>';
$evic=['found'=>'pin','enriched'=>'globe','audited'=>'activity','stage'=>'zap','sent'=>'send','opened'=>'eye','viewed'=>'eye','replied'=>'msg','error'=>'alert','note'=>'edit','scheduled'=>'clock','wa_manual'=>'wa','delivered'=>'check','read'=>'check','call'=>'mic','auto'=>'bot','booked'=>'cal'];
$checks=function($a,$t){if(!$a)return '';$o='<div class="ckl"><div class="ckh"><h4>'.$t.'</h4><span class="sc sc-'.($a['score']>=75?'g':($a['score']>=50?'a':'r')).' lg">'.$a['score'].'</span></div>';$by=[];foreach($a['checks'] as $c)$by[$c['cat']??'']=array_merge($by[$c['cat']??'']??[],[$c]);foreach($by as $cat=>$list){$o.='<div class="ckc">'.e($cat).(isset($a['cats'][$cat])?' · '.$a['cats'][$cat]:'').'</div>';foreach($list as $c)$o.='<div class="ck ck-'.$c['status'].'"><i>'.($c['status']==='pass'?'✓':($c['status']==='warn'?'!':'✕')).'</i><div><b>'.e($c['label']).'</b><small>'.e($c['detail']).'</small></div></div>';}return $o.'</div>';};
$isMaps=$l['source']==='maps';
?>
<div class="ph"><div><a class="lnk" href="<?=$l['is_lead']?url('leads'):($l['campaign_id']?url('campaign',['id'=>$l['campaign_id']]):url('prospects'))?>">← <?=$l['is_lead']?'Leads':e($l['keyword'].($l['location']?' · '.$l['location']:''))?></a><div class="phm"><?php if($l['is_lead']):?><?=sbadge($l['status'])?><?php else:?><span class="bdg bdg-gray"><?=icon('db')?>Scraped data</span><?php endif?><?php if($isMaps||$rep):?><?=badge($l['stage'])?><?php endif?><?=srcbadge($l['source'])?><?php if($l['position']):?><span class="muted sm">#<?=$l['position']?> on Google Maps</span><?php endif?></div></div>
<div class="pha"><?php if($l['phone']):?><a class="btn" href="tel:<?=e(preg_replace('/[^\d+]/','',$l['phone']))?>"><?=icon('phone')?>Call</a><?php if($rep):?><button class="btn btn-wa" onclick="A.sharePdf('report.php?t=<?=e($rep['token'])?>&dl=1','<?=e(addslashes('Audit-Report-'.preg_replace('/[^a-z0-9]+/i','-',$l['name']).'.pdf'))?>',<?=e(json_encode($waText))?>,'<?=e($waLink)?>')"><?=icon('wa')?>WhatsApp + PDF</button><?php else:?><a class="btn btn-wa" href="<?=e($waLink)?>" target="_blank" rel="noopener"><?=icon('wa')?>WhatsApp</a><?php endif?><?php endif?><?php if(!$l['is_lead']):?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="promote"><button class="btn btn-n"><?=icon('users')?>Move to Leads</button></form><?php endif?><button class="btn btn-y" onclick="A.modal('m-run')"><?=icon('zap')?><?=$rep?'Re-run audit':'Audit & report'?></button><div class="dd"><button class="btn" onclick="this.parentNode.classList.toggle('open')">More ▾</button><div class="ddm"><button onclick="A.modal('m-book')"><?=icon('cal')?>Book appointment</button><button onclick="A.modal('m-call')"><?=icon('mic')?>AI voice call</button><?php if($autos):?><button onclick="A.modal('m-auto')"><?=icon('bot')?>Start automation</button><?php endif?><?php if($rep):?><a href="report.php?t=<?=e($rep['token'])?>" target="_blank"><?=icon('eye')?>View PDF report</a><button onclick="A.copy('<?=e(base_url('report.php?t='.$rep['token']))?>')"><?=icon('link')?>Copy report link</button><?php endif?><button onclick="A.copy('<?=e(Booking::link($l))?>')"><?=icon('link')?>Copy booking link</button><hr><form method="post"><?=csrf_field()?><button name="a" value="won"><?=icon('check')?>Mark as Won</button></form><form method="post"><?=csrf_field()?><button name="a" value="lost"><?=icon('x')?>Not interested</button></form><form method="post" onsubmit="return confirm('Delete this record and all its history?')"><?=csrf_field()?><button class="red" name="a" value="delete"><?=icon('trash')?>Delete</button></form></div></div></div></div>
<?php if($busy):?><div class="card" style="border-color:#FDE68A;background:#FFFDF5"><div class="row"><span class="spin"></span><div style="flex:1"><b><?=e(stages()[$l['stage']][0]??$l['stage'])?> · <?=(int)$l['progress']?>%</b><div class="pb" style="margin:6px 0 2px"><i style="width:<?=(int)$l['progress']?>%"></i></div><small class="muted"><?=e($l['progress_msg'])?></small></div><form method="post" onsubmit="return confirm('Stop this process now?')"><?=csrf_field()?><input type="hidden" name="a" value="abort"><button class="btn btn-r"><?=icon('stop')?>Abort</button></form></div></div><span data-reload="5"></span>
