<div class="g2"><div class="card"><div class="card-h"><h3><span class="hi hi-t"><?=icon('cal')?></span>Appointments</h3><button class="btn btn-sm" onclick="A.modal('m-book')"><?=icon('plus')?>Book</button></div><?php if(!$appts):?><p class="muted sm">No appointments. Share the booking link or book one here.</p><?php endif?><?php foreach($appts as $ap):?><div class="msg"><div class="msg-h"><?=icon('cal')?><b><?=e(date('D, d M · h:i A',strtotime($ap['start_at'])))?></b><span class="bdg bdg-<?=['scheduled'=>'blue','completed'=>'green','no_show'=>'orange','cancelled'=>'gray'][$ap['status']]??'gray'?>"><?=e(ucfirst(str_replace('_',' ',$ap['status'])))?></span></div><p><?=e($ap['title'])?></p><?php if($ap['status']==='scheduled'):?><form method="post" class="row mt" style="gap:4px"><?=csrf_field()?><input type="hidden" name="a" value="appt"><input type="hidden" name="aid" value="<?=$ap['id']?>"><button class="btn btn-xs" name="st" value="completed">Done</button><button class="btn btn-xs" name="st" value="no_show">No-show</button><button class="btn btn-xs" name="st" value="cancelled">Cancel</button></form><?php endif?></div><?php endforeach?></div>
<div class="card"><div class="card-h"><h3><span class="hi hi-p"><?=icon('mic')?></span>AI calls</h3><button class="btn btn-sm" onclick="A.modal('m-call')" <?=$l['phone']?'':'disabled'?>><?=icon('phone')?>Call now</button></div><?php if(!$calls):?><p class="muted sm"><?=Voice::ready()?'No calls yet.':'Connect an AI voice provider in Settings → Voice calls.'?></p><?php endif?><?php foreach($calls as $c):?><div class="msg"><div class="msg-h"><?=icon('mic')?><b><?=e(ucfirst($c['provider']))?></b><span class="bdg bdg-<?=in_array($c['status'],['completed','ended','done'],true)?'green':($c['status']==='failed'?'red':'blue')?>"><?=e($c['status'])?></span><small><?=ago($c['created_at'])?><?=$c['duration']?' · '.gmdate('i:s',(int)$c['duration']):''?></small></div><?php if($c['summary']):?><p><?=e(mb_strimwidth($c['summary'],0,500,'…'))?></p><?php endif?><?php if($c['recording']):?><a class="lnk" href="<?=e($c['recording'])?>" target="_blank" rel="noopener"><?=icon('play')?>Recording</a><?php endif?><?php if($c['transcript']):?><details><summary class="sm muted">Transcript</summary><p style="white-space:pre-wrap"><?=e(mb_strimwidth($c['transcript'],0,4000,'…'))?></p></details><?php endif?></div><?php endforeach?></div></div>
<?php if($runs):?><div class="card"><div class="card-h"><h3><span class="hi hi-p"><?=icon('bot')?></span>Automations</h3></div><?php foreach($runs as $r):?><div class="msg"><div class="msg-h"><?=icon('bot')?><b><?=e($r['name'])?></b><span class="bdg bdg-<?=['running'=>'blue','waiting'=>'gold','done'=>'green','failed'=>'red','stopped'=>'gray','cancelled'=>'gray'][$r['status']]??'gray'?>"><?=e($r['status'])?></span><small><?=ago($r['created_at'])?></small><?php if(in_array($r['status'],['running','waiting'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="cancelrun"><input type="hidden" name="rid" value="<?=$r['id']?>"><button class="btn btn-xs">Stop</button></form><?php endif?></div><?php if($r['log']):?><p style="white-space:pre-wrap"><?=e(trim($r['log']))?></p><?php endif?></div><?php endforeach?></div><?php endif?>
<div class="g2"><div class="card"><div class="card-h"><h3><span class="hi hi-n"><?=icon('activity')?></span>Journey</h3><span class="muted sm"><?=count($ev)?> events</span></div><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="a" value="note"><input name="note" placeholder="Add a note to the journey…"><button class="btn btn-sm"><?=icon('plus')?></button></form><ul class="tl"><?php foreach($ev as $x):?><li class="ev-<?=e($x['type'])?>"><i><?=icon($evic[$x['type']]??'zap')?></i><div><span><?=e($x['message'])?></span><small><?=e(date('d M Y, h:i A',strtotime($x['created_at'])))?><?=$x['channel']?' · '.e($x['channel']):''?></small></div></li><?php endforeach?></ul></div>
<div class="card"><div class="card-h"><h3><span class="hi hi-g"><?=icon('msg')?></span>Messages</h3></div><?php if(!$msgs):?><div class="empty sm"><?=icon('msg')?><p>No messages yet.</p></div><?php endif?><?php foreach($msgs as $m):?><div class="msg msg-<?=e($m['direction'])?>"><div class="msg-h"><?=icon($m['channel']==='email'?'mail':'wa')?><b><?=e(ucfirst($m['channel']))?><?=$m['direction']==='in'?' · received':''?></b><?=chbadge($m['status'])?><small><?=ago($m['created_at'])?></small></div><?php if($m['subject']):?><b class="sm"><?=e($m['subject'])?></b><?php endif?><p><?=nl2br(e(mb_strimwidth((string)$m['body'],0,600,'…')))?></p></div><?php endforeach?></div></div>
</div></div>
<div class="md" id="m-run"><form class="md-b" method="post"><?=csrf_field()?><div class="md-h"><h3><span class="hi hi-y"><?=icon('zap')?></span>Audit &amp; report</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><label>Report prompt (has website)<?=$psel('pw',$pw)?></label><label>Report prompt (no website)<?=$psel('pn',$pn)?></label><label class="chk"><input type="checkbox" name="auto" value="1" <?=setting('auto_contact')==='1'&&!$rep?'checked':''?>> Send by Email &amp; WhatsApp when the report is ready</label><div class="md-f"><?php if($au):?><button class="btn" name="a" value="report"><?=icon('file')?>Only rewrite report</button><?php endif?><button class="btn btn-y" name="a" value="initiate"><?=icon('play')?>Full audit + report</button></div></form></div>
<div class="md" id="m-book"><form class="md-b" method="post"><?=csrf_field()?><input type="hidden" name="a" value="book"><div class="md-h"><h3><span class="hi hi-t"><?=icon('cal')?></span>Book appointment</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><label>Date &amp; time<input type="datetime-local" name="at" required></label><label>Notes<textarea name="notes" rows="2"></textarea></label><p class="hint">Or send them their personal booking link: <a class="lnk" href="#" data-copy="<?=e(Booking::link($l))?>">copy link</a></p><div class="md-f"><button class="btn btn-y"><?=icon('check')?>Book</button></div></form></div>
<div class="md" id="m-call"><form class="md-b" method="post"><?=csrf_field()?><input type="hidden" name="a" value="call"><div class="md-h"><h3><span class="hi hi-p"><?=icon('mic')?></span>AI voice call</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><?php if(!Voice::ready()):?><div class="al al-warn"><?=icon('alert')?><span>No voice provider connected. <a href="<?=url('settings',['tab'=>'voice'])?>">Connect Sarvam AI, Bland, Vapi or Retell</a>.</span></div><?php endif?><p class="muted">The AI calls <b><?=e($l['phone'])?></b>. Leave blank to use the default script from Settings.</p><label>First sentence<input name="first" placeholder="<?=e(setting('voice_first_message'))?>"></label><label>Task / script for this call<textarea name="task" rows="4" placeholder="<?=e(setting('voice_task'))?>"></textarea></label><div class="md-f"><button class="btn btn-y" <?=Voice::ready()&&$l['phone']?'':'disabled'?>><?=icon('phone')?>Start call</button></div></form></div>
<?php if($autos):?><div class="md" id="m-auto"><form class="md-b" method="post"><?=csrf_field()?><input type="hidden" name="a" value="auto"><div class="md-h"><h3><span class="hi hi-p"><?=icon('bot')?></span>Start automation</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><label>Automation<select name="aid"><?php foreach($autos as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach?></select></label><div class="md-f"><button class="btn btn-y"><?=icon('play')?>Start</button></div></form></div><?php endif?>
